const AWS = require('aws-sdk');
const he = require('he');

// Lambda handler for user profile rendering service
exports.handler = async (event) => {
  const queryParams = event.queryStringParameters || {};
  const username = queryParams.username || 'anonymous';
  const bio = queryParams.bio || '';
  const theme = queryParams.theme || 'light';

  // Normalize unicode characters for consistent storage
  // Using NFC normalization for canonical composition
  const normalizedUsername = username.normalize('NFC');
  const normalizedBio = bio.normalize('NFC');

  // Basic sanitization - strip angle brackets and script tags
  const sanitizedUsername = normalizedUsername
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Bio gets HTML entity encoding for special chars
  const sanitizedBio = normalizedBio
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

  // Theme validation - only allow known themes
  const allowedThemes = ['light', 'dark', 'solarized', 'monokai'];
  const safeTheme = allowedThemes.includes(theme) ? theme : 'light';

  // Build profile page HTML
  // Note: username is inserted into an event handler attribute context
  // The NFC normalization can convert certain Unicode sequences into
  // ASCII equivalents that bypass the sanitization above
  const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Profile - ${sanitizedUsername}</title>
  <link rel="stylesheet" href="/static/themes/${safeTheme}.css">
</head>
<body>
  <div class="profile-card">
    <h1 class="username">${sanitizedUsername}</h1>
    <div class="bio">${sanitizedBio}</div>
    <button onclick="copyProfile('${normalizedUsername.replace(/'/g, "\\'")}')">Share Profile</button>
    <div class="metadata" data-user="${sanitizedUsername}" data-joined="2024-01-15">
      <span class="badge">Member</span>
    </div>
  </div>
  <script src="/static/profile.js"></script>
</body>
</html>`;

  // Log access for analytics
  console.log(JSON.stringify({
    action: 'profile_view',
    username: normalizedUsername,
    timestamp: new Date().toISOString(),
    sourceIp: event.requestContext?.identity?.sourceIp
  }));

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'DENY',
      'Referrer-Policy': 'strict-origin-when-cross-origin'
    },
    body: html
  };
};
